const circuits=[{name:'微光环线',sub:'入门 · 宽弯热身',limit:45,three:18,two:28,points:[[850,650],[540,650],[370,570],[310,380],[420,230],[720,200],[950,300],[1020,480]]},{name:'折返之间',sub:'进阶 · 连续发夹弯',limit:60,three:26,two:40,points:[[850,680],[500,680],[260,570],[280,330],[470,230],[600,350],[720,450],[850,330],[1020,230],[1110,440],[1040,610]]},{name:'午夜回廊',sub:'挑战 · 长距离竞速',limit:70,three:32,two:48,points:[[850,700],[550,700],[270,620],[210,400],[330,180],[570,170],[680,300],[560,450],[740,490],[900,380],[870,190],[1080,230],[1150,470],[1040,660]]}];
