let save={coins:0,best:[0,0,0],times:[null,null,null],owned:[0],skin:0};try{let s=JSON.parse(localStorage.getItem('fingertip-v1'));if(s&&Array.isArray(s.best)&&Array.isArray(s.owned))save={...save,...s}}catch{}
let selected=0,mode='menu',w,h,dpr,scale,ox,oy,road=[],gates=[],car,elapsed=0,nextGate=1,marks=[],sparks=[],trail=[],last=0,joy=null,keys={},soundOn=false,audio,osc,gain,wasDrift=false,toastTimer;
function persist(){try{localStorage.setItem('fingertip-v1',JSON.stringify(save))}catch{}}function toast(t){$('toast').textContent=t;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),2200)}
function menuTracks(){ $('coins').textContent=save.coins;$('tracks').innerHTML=circuits.map((c,i)=>`<button class="track ${selected===i?'active':''}" data-track="${i}"><span class="trackNum">0${i+1}</span><span><strong>${c.name}</strong><small>${c.sub}</small></span><span class="trackStars">${'★'.repeat(save.best[i])}${'☆'.repeat(3-save.best[i])}</span></button>`).join('');document.querySelectorAll('[data-track]').forEach(b=>b.onclick=()=>{selected=+b.dataset.track;buildTrack();resetCar();menuTracks()})}
function cat(a,b,c,d,t){return .5*((2*b)+(-a+c)*t+(2*a-5*b+4*c-d)*t*t+(-a+3*b-3*c+d)*t*t*t)}
function buildTrack(){const p=circuits[selected].points,n=p.length;road=[];for(let i=0;i<n;i++)for(let j=0;j<24;j++){let t=j/24;road.push({x:cat(p[(i+n-1)%n][0],p[i][0],p[(i+1)%n][0],p[(i+2)%n][0],t),y:cat(p[(i+n-1)%n][1],p[i][1],p[(i+1)%n][1],p[(i+2)%n][1],t)})}gates=Array.from({length:16},(_,i)=>road[Math.floor(i*road.length/16)])}
function resetCar(){let p=road[0],q=road[3];car={x:p.x,y:p.y,a:Math.atan2(q.y-p.y,q.x-p.x),vx:0,vy:0};elapsed=0;nextGate=1;marks=[];sparks=[];trail=[];joy=null;keys={};wasDrift=false}
function resize(){w=innerWidth;h=innerHeight;dpr=Math.min(devicePixelRatio||1,2);canvas.width=w*dpr;canvas.height=h*dpr;scale=Math.min(w/1350,h/950);ox=(w-1350*scale)/2;oy=(h-950*scale)/2;if(w<700){scale=Math.min(w/1300,(h-190)/850);ox=(w-1300*scale)/2;oy=(h-850*scale)/2+35}}
function path(){ctx.beginPath();road.forEach((p,i)=>i?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y));ctx.closePath()}
function line(width,color){path();ctx.lineWidth=width;ctx.strokeStyle=color;ctx.stroke()}
function draw(t){ctx.setTransform(dpr,0,0,dpr,0,0);ctx.fillStyle='#0c111b';ctx.fillRect(0,0,w,h);ctx.strokeStyle='#152130';ctx.lineWidth=1;let grid=55*scale;for(let x=ox%grid;x<w;x+=grid){ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,h);ctx.stroke()}for(let y=oy%grid;y<h;y+=grid){ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(w,y);ctx.stroke()}
ctx.save();ctx.translate(ox,oy);ctx.scale(scale,scale);ctx.lineJoin='round';ctx.lineCap='round';ctx.save();ctx.translate(0,16);line(118,'#050a11');ctx.restore();ctx.shadowColor='#7bffb4';ctx.shadowBlur=15;line(111,'#416458');ctx.shadowBlur=0;line(105,'#162c2b');line(96,'#27343f');line(88,'#202b36');ctx.setLineDash([14,20]);line(1.5,'#53606a');ctx.setLineDash([]);
// Raised edge lights and directional chevrons.
for(let i=0;i<road.length;i+=18){let p=road[i],q=road[(i+2)%road.length],a=Math.atan2(q.y-p.y,q.x-p.x);ctx.save();ctx.translate(p.x,p.y);ctx.rotate(a);ctx.strokeStyle='#b9ff7066';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(-5,-6);ctx.lineTo(2,0);ctx.lineTo(-5,6);ctx.stroke();ctx.restore()}
let p=road[0],q=road[2],angle=Math.atan2(q.y-p.y,q.x-p.x);ctx.save();ctx.translate(p.x,p.y);ctx.rotate(angle);for(let row=0;row<2;row++)for(let j=0;j<8;j++){ctx.fillStyle=(row+j)%2?'#26313a':'#c7d5da';ctx.fillRect(row*9-9,j*11-44,9,11)}ctx.fillStyle='#b5ff64';ctx.font='bold 13px monospace';ctx.fillText('START / FINISH',-60,-65);ctx.restore();
if(mode==='race'){let g=gates[nextGate%16];ctx.save();ctx.translate(g.x,g.y);ctx.strokeStyle='#b7ff6577';ctx.lineWidth=2;ctx.beginPath();ctx.arc(0,0,26+Math.sin(t*.004)*3,0,Math.PI*2);ctx.stroke();ctx.fillStyle='#b7ff65';ctx.font='12px monospace';ctx.textAlign='center';ctx.fillText(nextGate===16?'FINISH':'›',0,4);ctx.restore()}
ctx.lineWidth=2.7;for(const m of marks){ctx.globalAlpha=m.life*.45;ctx.strokeStyle='#060c13';ctx.beginPath();ctx.moveTo(m.x,m.y);ctx.lineTo(m.px,m.py);ctx.stroke()}ctx.globalAlpha=1;
const color=paints[save.skin]?.color||paints[0].color;for(let i=1;i<trail.length;i++){ctx.strokeStyle=color;ctx.globalAlpha=i/trail.length*.25;ctx.lineWidth=i/trail.length*7;ctx.beginPath();ctx.moveTo(trail[i-1].x,trail[i-1].y);ctx.lineTo(trail[i].x,trail[i].y);ctx.stroke()}ctx.globalAlpha=1;
ctx.save();ctx.translate(car.x,car.y);ctx.rotate(car.a);ctx.fillStyle='#0008';ctx.fillRect(-16,-8,34,20);ctx.shadowBlur=20;ctx.shadowColor=color;ctx.fillStyle=color;ctx.beginPath();ctx.roundRect(-19,-10,38,20,5);ctx.fill();ctx.shadowBlur=0;ctx.fillStyle='#142a38';ctx.fillRect(0,-8,8,16);ctx.fillStyle='#23434d';ctx.fillRect(-12,-7,8,14);ctx.fillStyle='#eeffff';ctx.fillRect(15,-9,3,4);ctx.fillRect(15,5,3,4);ctx.fillStyle='#ff5f7e';ctx.fillRect(-19,-8,2,4);ctx.fillRect(-19,4,2,4);ctx.fillStyle='#0a121c';ctx.fillRect(-13,-13,10,3);ctx.fillRect(-13,10,10,3);ctx.fillRect(9,-13,8,3);ctx.fillRect(9,10,8,3);ctx.restore();
for(const s of sparks){ctx.globalAlpha=s.life;ctx.fillStyle=color;ctx.fillRect(s.x,s.y,3,3)}ctx.globalAlpha=1;ctx.restore();
if(joy&&mode==='race'){ctx.strokeStyle='#c3ff8977';ctx.fillStyle='#b5ff6410';ctx.lineWidth=2;ctx.beginPath();ctx.arc(joy.x,joy.y,65,0,Math.PI*2);ctx.fill();ctx.stroke();ctx.fillStyle='#b7ff65aa';ctx.beginPath();ctx.arc(joy.x+joy.dx,joy.y+joy.dy,22,0,Math.PI*2);ctx.fill()}}
function nearest(x,y){let min=Infinity;for(let i=0;i<road.length;i++){let a=road[i],b=road[(i+1)%road.length],dx=b.x-a.x,dy=b.y-a.y,u=Math.max(0,Math.min(1,((x-a.x)*dx+(y-a.y)*dy)/(dx*dx+dy*dy)));min=Math.min(min,Math.hypot(x-a.x-u*dx,y-a.y-u*dy))}return min}
function update(dt){elapsed+=dt;let dx=0,dy=0,amount=0;if(joy){dx=joy.dx;dy=joy.dy;amount=Math.min(1,Math.hypot(dx,dy)/65)}else{dx=(keys.ArrowRight||keys.d?1:0)-(keys.ArrowLeft||keys.a?1:0);dy=(keys.ArrowDown||keys.s?1:0)-(keys.ArrowUp||keys.w?1:0);amount=Math.min(1,Math.hypot(dx,dy))}let turn=0;if(amount>.08){let target=Math.atan2(dy,dx);turn=Math.atan2(Math.sin(target-car.a),Math.cos(target-car.a));car.a+=Math.max(-3.8*dt,Math.min(3.8*dt,turn))}const old={x:car.x,y:car.y},speed=Math.hypot(car.vx,car.vy),off=nearest(car.x,car.y)>43,drift=speed>80&&(Math.abs(turn)>.38||keys[' ']);let forward=car.vx*Math.cos(car.a)+car.vy*Math.sin(car.a),side=-car.vx*Math.sin(car.a)+car.vy*Math.cos(car.a);side*=Math.exp(-(drift?2.5:9)*dt);forward+=amount*260*dt;forward*=Math.exp(-(off?3.5:amount>.08?.65:2.2)*dt);forward=Math.min(off?125:330,Math.max(0,forward));car.vx=forward*Math.cos(car.a)-side*Math.sin(car.a);car.vy=forward*Math.sin(car.a)+side*Math.cos(car.a);car.x+=car.vx*dt;car.y+=car.vy*dt;
if(drift){for(const offset of [-8,8]){let nx=-Math.sin(car.a)*offset,ny=Math.cos(car.a)*offset;marks.push({x:old.x+nx,y:old.y+ny,px:car.x+nx,py:car.y+ny,life:1})}if(Math.random()<.4)sparks.push({x:car.x-12*Math.cos(car.a),y:car.y-12*Math.sin(car.a),life:1});if(!wasDrift&&navigator.vibrate)navigator.vibrate(16)}wasDrift=drift;for(const m of marks)m.life-=dt*.025;marks=marks.filter(m=>m.life>0).slice(-2500);for(const s of sparks)s.life-=dt*2;sparks=sparks.filter(s=>s.life>0);trail.push({x:car.x,y:car.y});if(trail.length>24)trail.shift();
if(osc&&gain){osc.frequency.setTargetAtTime(45+speed*.4,audio.currentTime,.1);gain.gain.setTargetAtTime(soundOn?(.015+speed/20000):0,audio.currentTime,.1)}let g=gates[nextGate%16];if(Math.hypot(car.x-g.x,car.y-g.y)<58){nextGate++;if(nextGate>16){finish(true);return}}if(elapsed>=circuits[selected].limit){finish(false);return}if(car.x<70||car.x>1280||car.y<60||car.y>860){car.x=old.x;car.y=old.y;car.vx*=.3;car.vy*=.3}
$('timer').textContent=(circuits[selected].limit-elapsed).toFixed(2);$('progress').textContent=`${Math.floor((nextGate-1)/16*100)}% / 1 圈`;$('speed').firstElementChild.textContent=Math.round(speed*.5);$('raceHint').textContent=off?'驶回赛道，加速恢复':drift?'DRIFT / 漂移中':'跟随绿色路标，完成一圈'}
function loop(t){let dt=Math.min((t-last)/1000,.033);last=t;if(mode==='race')update(dt);draw(t);requestAnimationFrame(loop)}
function start(){resetCar();mode='race';$('menu').hidden=true;$('hud').hidden=false;$('overlay').hidden=true;$('trackName').textContent=`0${selected+1} / ${circuits[selected].name}`;$('pause').textContent='暂停'}
function finish(win){mode='result';joy=null;keys={};if(gain)gain.gain.value=0;const c=circuits[selected],stars=win?(elapsed<=c.three?3:elapsed<=c.two?2:1):0,earned=Math.max(0,stars-save.best[selected])*20;save.coins+=earned;save.best[selected]=Math.max(save.best[selected],stars);if(win)save.times[selected]=Math.min(save.times[selected]||Infinity,elapsed);persist();menuTracks();$('resultLabel').textContent=win?'CIRCUIT COMPLETE':'TIME IS UP';$('resultTitle').textContent=win?'漂亮的过弯。':'再试一次。';$('resultBody').innerHTML=`<div class="bigStars">${'★'.repeat(stars)}${'☆'.repeat(3-stars)}</div><div class="resultStat">本次用时<b>${elapsed.toFixed(2)} 秒</b></div><div class="resultStat">金币奖励<b>+${earned}</b></div><div class="resultStat">三星目标<b>${c.three} 秒以内</b></div><p>${win?'每提升一颗历史最佳星星，奖励 20 金币。':'试着提前转向；偏离赛道会降低速度。'}</p>`;$('overlay').hidden=false;$('continue').textContent='再跑一圈'}
function home(){mode='menu';joy=null;keys={};$('menu').hidden=false;$('hud').hidden=true;$('overlay').hidden=true;if(gain)gain.gain.value=0;resetCar();menuTracks()}
$('start').onclick=start;$('restart').onclick=start;$('pause').onclick=()=>{if(mode!=='race')return;mode='paused';joy=null;keys={};if(gain)gain.gain.value=0;$('resultLabel').textContent='TAKE A BREATH';$('resultTitle').textContent='休息一下';$('resultBody').innerHTML='<p>赛道会等你。准备好后继续驾驶。</p>';$('continue').textContent='继续驾驶';$('overlay').hidden=false};$('continue').onclick=()=>{if(mode==='paused'){mode='race';$('overlay').hidden=true}else start()};$('back').onclick=home;
function shop(){ $('skins').innerHTML=paints.map((p,i)=>`<div class="skin"><span><i style="background:${p.color};color:${p.color}"></i>${p.name}</span><button data-skin="${i}">${save.skin===i?'已装备':save.owned.includes(i)?'装备':p.price+' 金币'}</button></div>`).join('');document.querySelectorAll('[data-skin]').forEach(b=>b.onclick=()=>{let i=+b.dataset.skin;if(!save.owned.includes(i)){if(save.coins<paints[i].price){toast('金币不足，挑战更多星星吧');return}save.coins-=paints[i].price;save.owned.push(i)}save.skin=i;persist();menuTracks();shop()})}$('shopBtn').onclick=()=>{shop();$('garage').hidden=false};$('closeShop').onclick=()=>{$('garage').hidden=true};
canvas.addEventListener('pointerdown',e=>{if(mode!=='race'||joy)return;canvas.setPointerCapture(e.pointerId);joy={id:e.pointerId,x:e.clientX,y:e.clientY,dx:0,dy:0}});canvas.addEventListener('pointermove',e=>{if(!joy||e.pointerId!==joy.id)return;let dx=e.clientX-joy.x,dy=e.clientY-joy.y,len=Math.hypot(dx,dy),ratio=Math.min(1,65/(len||1));joy.dx=dx*ratio;joy.dy=dy*ratio});for(const event of ['pointerup','pointercancel','lostpointercapture'])canvas.addEventListener(event,e=>{if(joy?.id===e.pointerId)joy=null});addEventListener('keydown',e=>{if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight',' '].includes(e.key))e.preventDefault();keys[e.key.length===1?e.key.toLowerCase():e.key]=true;if(e.key==='Escape'&&mode==='race')$('pause').click()});addEventListener('keyup',e=>keys[e.key.length===1?e.key.toLowerCase():e.key]=false);addEventListener('blur',()=>{if(mode==='race')$('pause').click();keys={};joy=null});document.addEventListener('visibilitychange',()=>{if(document.hidden&&mode==='race')$('pause').click()});
$('sound').onclick=()=>{try{if(!audio){audio=new(window.AudioContext||window.webkitAudioContext)();osc=audio.createOscillator();gain=audio.createGain();osc.type='sawtooth';gain.gain.value=0;osc.connect(gain);gain.connect(audio.destination);osc.start()}audio.resume();soundOn=!soundOn;$('sound').textContent='音效 '+(soundOn?'开':'关');if(!soundOn)gain.gain.value=0}catch{toast('当前浏览器暂不支持音效')}};addEventListener('resize',resize);buildTrack();resetCar();resize();menuTracks();requestAnimationFrame(loop);
